  final bool shouldPushToHome;

  @override
  ConsumerState<StackRestoreProgressView> createState() =>
      _StackRestoreProgressViewState();
}

class _StackRestoreProgressViewState
    extends ConsumerState<StackRestoreProgressView> {
  bool isDesktop = Util.isDesktop;

  Future<void> _cancel() async {
    bool shouldPop = false;
    unawaited(
      showDialog<void>(
        barrierDismissible: false,
        context: context,
        builder: (_) => WillPopScope(
          onWillPop: () async {
            return shouldPop;
          },
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Material(
                color: Colors.transparent,
                child: Center(
                  child: Text(
                    l10n.restoreCancelling,
                    style: STextStyles.pageTitleH2(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .textWhite,
                    ),
                  ),
                ),
              ),
              const SizedBox(height: 64),
              const Center(child: LoadingIndicator(width: 100)),
            ],
          ),
        ),
      ),
    );

    // Once the restore has returned nothing would answer the request:
    // there is nothing left to cancel.
    if (!_restoreEnded) await SWB.cancelRestore();
    shouldPop = true;

    int count = 0;

    if (mounted) {
      !isDesktop
          ? Navigator.of(context).popUntil(
              ModalRoute.withName(
                widget.fromFile
                    ? RestoreFromEncryptedStringView.routeName
                    : StackBackupView.routeName,
              ),
            )
          : Navigator.of(context).popUntil((_) => count++ >= 2);
    }
  }

  Future<bool> _requestCancel() async {
    final result = await showDialog<dynamic>(
      barrierDismissible: false,
      context: context,
      builder: (_) => const CancelStackRestoreDialog(),
    );

    if (result is bool && result) {
      return true;
    }
    return false;
  }

  Future<void> _restore() async {
    ref.refresh(stackRestoringUIStateProvider);
    final uiState = ref.read(stackRestoringUIStateProvider);

    // Every step reported but the restore doesn't return (stuck loading
    // the wallets afterwards): don't leave "Cancel" up forever.
    var graceStarted = false;
    void onChange() {
      if (graceStarted || !uiState.done) return;
      graceStarted = true;
      Future<void>.delayed(const Duration(seconds: 20), () {
        if (mounted && !_restoreEnded && !_success && uiState.done) {
          Logging.instance.w("SWB restore: steps done but still running");
          setState(() => _success = true);
        }
      });
    }

    uiState.addListener(onChange);
    bool? finished;
    try {
      finished = await SWB.restoreStackWalletJSON(
        widget.jsonString,
        uiState,
        ref.read(secureStoreProvider),
      );
    } catch (e, s) {
      Logging.instance.e("SWB restore failed", error: e, stackTrace: s);
    } finally {
      _restoreEnded = true;
      uiState.removeListener(onChange);
    }
    // The backup's theme. A cancelled restore puts this device's settings
    // back, and its theme never changed.
    if (mounted && finished != false) applyThemePrefs(context, ref);
    Logging.instance.i("SWB restore ended: $finished, done: ${uiState.done}");

    // Every step has its result (all ticks, or some failed): the restore
    // is over, so OK rather than "Cancel", even if loading the wallets
    // afterwards failed (OK adds them). Not when it was cancelled.
    if (mounted && finished != false && uiState.done) {
      setState(() {
        _success = true;
      });
    }
  }

  bool _success = false;

  /// [SWB.restoreStackWalletJSON] returned (or threw).
  bool _restoreEnded = false;

  Future<bool> _onWillPop() async {
    if (_success) {
      _addWalletsToHomeView();
      return true;
    }

    final shouldCancel = await _requestCancel();
    if (shouldCancel) {
      await _cancel();
      return true;
    } else {
      return false;
    }
  }

  Widget _getIconForState(StackRestoringStatus state) {
    switch (state) {
      case StackRestoringStatus.waiting:
        return SvgPicture.asset(
          Assets.svg.loader,
          color: Theme.of(context)
              .extension<StackColors>()!
              .buttonBackSecondary,
        );
      case StackRestoringStatus.restoring:
        return SvgPicture.asset(
          Assets.svg.loader,
          color: Theme.of(context).extension<StackColors>()!.accentColorGreen,
        );
      case StackRestoringStatus.success:
        return SvgPicture.asset(
          Assets.svg.checkCircle,
          color: Theme.of(context).extension<StackColors>()!.accentColorGreen,
        );
      case StackRestoringStatus.failed:
        return SvgPicture.asset(
          Assets.svg.circleAlert,
          color: Theme.of(context).extension<StackColors>()!.textError,
        );
    }
  }

  void _addWalletsToHomeView() {
    ref
        .read(pWallets)
        .loadAfterStackRestore(
          ref.read(prefsChangeNotifierProvider),
          ref.read(stackRestoringUIStateProvider).wallets,
          Util.isDesktop,
        );
  }

  @override
  void initState() {
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      unawaited(_restore());
    });
    super.initState();
  }

